(()=>{function showMix(){const m=window.resolveStudyModel();const carbonFmt=v=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:6}).format(v);document.querySelectorAll('[data-disposal-status]').forEach(e=>e.textContent='Carbon model: mobile-phase production — 3.69 kg CO₂e/L prepared mobile phase; disposal — 1.57 kg CO₂e/L waste. Does not include transportation CO₂ calculations.');document.querySelectorAll('[data-production-breakdown]').forEach(e=>e.textContent='Estimated CO₂e prevented = fresh prepared mobile phase avoided × 3.69 + waste avoided × 1.57. These factors apply to whole-mixture litres, without a solvent-share multiplier.');const waterInput=document.getElementById('calc-water-cost'),waterValue=Number(waterInput.value),water=Number.isFinite(waterValue)?Math.max(0,Math.min(1000000,waterValue)):0,price=Number(document.getElementById('calc-solvent-cost').value)||0,eur=v=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(v);const waterSet=(key,value)=>document.querySelectorAll('[data-water-'+key+']').forEach(e=>e.textContent=value);waterSet('volume',new Intl.NumberFormat('en-IE',{maximumFractionDigits:4}).format(m.bufferPercent/100)+' L');waterSet('price',eur(water)+'/L');waterSet('contribution',eur(water*m.bufferPercent/100)+'/L');waterSet('total',eur(price)+'/L');const f=v=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:2}).format(v)+'%';for(const [key,value] of [['buffer',m.bufferPercent],['acn',m.acnPercent],['methanol',m.methanolPercent]]){document.querySelectorAll('[data-mix-'+key+']').forEach(e=>e.textContent=f(value));document.querySelectorAll('[data-mix-segment="'+key+'"]').forEach(e=>e.style.width=value+'%');}document.querySelectorAll('.mix-track').forEach(e=>e.setAttribute('aria-label',f(m.bufferPercent)+' aqueous buffer, '+f(m.acnPercent)+' acetonitrile, '+f(m.methanolPercent)+' methanol'));}document.addEventListener('resolve-model',showMix);showMix();})();